class Solution {
public:
    int pseudoPalindromicPaths (TreeNode* root) {
        int count = 0;
        dfs(root, 0, count);
        return count;
    }
private:
    void dfs(TreeNode* node, int mask, int& count) {
        if (!node) return;
        mask ^= (1 << node->val);
        if (!node->left && !node->right) {
            if ((mask & (mask - 1)) == 0) {
                ++count;
            }
        } else {
            dfs(node->left, mask, count);
            dfs(node->right, mask, count);
        }
    }
};
